import './style.css';
import './discovery.css';
import spotifyPlaylist from './spotify-playlist.json';
import { searchCatalog, isLocalAudio } from './catalog.js';
import { renderHomeFeature, renderCatalog, renderSpotify, spotifyLibraryTracks, providerLink, spotifyMark } from './discovery.js';
import { demoTracks } from './demo.js';
import { MusicPlayer } from './player.js';
import { loadLibrary,saveTrack,updateTrack,getAudioBlob,removeTrack,savePlaylist,saveCatalogPlaylist,addCatalogTrack,removePlaylist,saveSetting,importAudioFiles } from './library.js';
import { escapeHtml as e,formatTime,searchTracks,shuffled,safeArtwork,displayArtwork,parseLyrics,currentLyricIndex,moveItem } from './domain.js';

const paths={music:'M9 18V5l12-2v13M9 9l12-2M9 18a3 3 0 1 1-3-3c1.7 0 3 .6 3 3Zm12-2a3 3 0 1 1-3-3c1.7 0 3 .6 3 3Z',home:'m3 10 9-7 9 7v10H3V10Zm6 10v-7h6v7',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',radio:'M5 5a10 10 0 0 0 0 14M19 5a10 10 0 0 1 0 14M8 8a6 6 0 0 0 0 8M16 8a6 6 0 0 1 0 8M12 12h.01',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',album:'M3 3h18v18H3zM17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM12 12h.01',artist:'M20 21v-2a7 7 0 0 0-14 0v2M17 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',list:'M9 5h12M9 12h12M9 19h12M3 5h.01M3 12h.01M3 19h.01',plus:'M12 4v16M4 12h16',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',play:'m8 4 13 8-13 8V4Z',pause:'M7 4v16M17 4v16',next:'m4 4 11 8-11 8V4ZM19 4v16',previous:'m20 4-11 8 11 8V4ZM5 4v16',shuffle:'M3 5h3c5 0 7 14 12 14h3m-4-4 4 4-4 4M3 19h3c2 0 4-4 6-7 2-3 4-7 6-7h3m-4-4 4 4-4 4',repeat:'M17 2l4 4-4 4M3 10V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14 0v2a2 2 0 0 1-2 2H3',volume:'m11 5-6 4H2v6h3l6 4V5ZM15 8a6 6 0 0 1 0 8m4-12a11 11 0 0 1 0 16',mute:'m11 5-6 4H2v6h3l6 4V5Zm5 4 5 6m0-6-5 6',more:'M4 12h.01M12 12h.01M20 12h.01',close:'m6 6 12 12M18 6 6 18',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',down:'m5 9 7 7 7-7',up:'m5 15 7-7 7 7',lyrics:'M4 3h16v15H8l-4 4V3ZM8 7h8M8 11h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-8 4-2-1 2-4 2 1 3-2V3h5v3l3 2 2-1 2 4-2 1v3l2 1-2 4-2-1-3 2v2H9v-2l-3-2-2 1-2-4 2-1v-3Z',check:'m4 12 5 5L20 6',delete:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',edit:'m16 3 5 5L8 21H3v-5L16 3Z',sun:'M12 3V1M12 23v-2M3 12H1m22 0h-2M4 4 2 2m20 20-2-2M4 20l-2 2M22 2l-2 2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z',folder:'M3 6h7l2 3h9v12H3V6Z',fullscreen:'M3 9V3h6m6 0h6v6m0 6v6h-6M9 21H3v-6',headphones:'M3 14v-2a9 9 0 0 1 18 0v2M3 13h4v8H3v-8Zm14 0h4v8h-4v-8Z',info:'M12 10v7M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.music}"/></svg>`;
const button=(action,label,ico,extra='',classes='icon-button')=>`<button class="${classes}" data-action="${action}" aria-label="${e(label)}" title="${e(label)}" ${extra}>${icon(ico)}</button>`;
const app=document.querySelector('#app'), dialog=document.querySelector('#dialog');
let state={tracks:[],playlists:[],settings:{},view:'new',viewId:'',query:'',searchScope:'library',sort:'title',panel:null,sidebar:false,loading:true,error:'',importing:false};
let toastTimer, lyricsTargetId, renderedLyric=-1, saveQueueTimer;
let catalog = { status:'idle', results:[], query:'', error:'', skipped:0 };
let catalogTimer, catalogController, catalogGeneration=0, catalogLastRequest=0;
let catalogSavePending=false, spotifySavePending=false;
const spotifySavedId='spotify-playlist:'+spotifyPlaylist.spotifyId;
const findTrack=id=>state.tracks.find(track=>track.id===id);
const player=new MusicPlayer({findTrack,readBlob:getAudioBlob});
const cover=track=>displayArtwork(track?.artwork);
const albumKey=track=>JSON.stringify([track.album,track.artist]);
const currentPlaylist=()=>state.playlists.find(list=>list.id===state.viewId);
function notify(message){const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),4500);}
function navigate(view,id=''){state.sidebar=false;location.hash=`${view}${id?`/${encodeURIComponent(id)}`:''}`;if(state.view===view&&state.viewId===id)render();}
function readRoute(){cancelCatalog();const [view,...parts]=location.hash.slice(1).split('/');state.view=['home','new','radio','songs','albums','artists','favorites','recent','playlist','album','artist','search','spotify'].includes(view)?view:'new';try{state.viewId=decodeURIComponent(parts.join('/'));}catch{state.viewId='';}render();if(state.view==='search'&&state.searchScope==='catalog')scheduleCatalog();window.scrollTo(0,0);}
async function persistSetting(key,value){await saveSetting(key,value);state.settings[key]=value;}
function libraryTracks(){return state.tracks;}
function routeTracks(){let result=libraryTracks();if(state.view==='favorites')result=result.filter(t=>t.favorite);if(state.view==='recent')result=result.filter(t=>t.lastPlayed).sort((a,b)=>b.lastPlayed-a.lastPlayed);if(state.view==='playlist')result=(currentPlaylist()?.trackIds||[]).map(findTrack).filter(Boolean);if(state.view==='album')result=result.filter(t=>albumKey(t)===state.viewId);if(state.view==='artist')result=result.filter(t=>t.artist===state.viewId);if(state.query&&state.view==='search')result=searchTracks(result,state.query);if(!['playlist','recent','album','artist'].includes(state.view))result=[...result].sort(state.sort==='added'?(a,b)=>b.addedAt-a.addedAt:state.sort==='artist'?(a,b)=>a.artist.localeCompare(b.artist):(a,b)=>a.title.localeCompare(b.title));return result;}
function albums(tracks=libraryTracks()){const map=new Map();for(const track of tracks){if(!track.album.trim())continue;const key=albumKey(track);if(!map.has(key))map.set(key,{id:key,name:track.album,artist:track.artist,cover:cover(track),tracks:[]});map.get(key).tracks.push(track);}return [...map.values()];}
function navItem(view,label,ico,extra=''){return `<button data-action="navigate" data-view="${view}" class="nav-item ${state.view===view?'active':''}" ${extra}>${icon(ico,19)}<span>${label}</span></button>`;}
function render(){
  document.documentElement.dataset.theme=state.settings.theme||'light';
  const active=player.track;
  app.innerHTML=`<aside class="sidebar ${state.sidebar?'open':''}" aria-label="Music navigation"><button class="brand" data-action="navigate" data-view="new">${icon('music',28)}<strong>Music</strong><span>LAB</span></button><button class="sidebar-search" data-action="navigate" data-view="search">${icon('search',15)}<span>Search</span><kbd>⌘ K</kbd></button><nav>${navItem('home','Home','home')}${navItem('new','New','grid')}${navItem('radio','Radio','radio')}<div class="nav-label">Library</div>${navItem('recent','Recently Played','clock')}${navItem('artists','Artists','artist')}${navItem('albums','Albums','album')}${navItem('songs','Songs','music')}${navItem('favorites','Favorite Songs','heart')}<div class="nav-label playlist-label">Playlists ${button('create-playlist','Create playlist','plus')}</div><button class="nav-item pinned-playlist ${state.view==='spotify'?'active':''}" data-action="navigate" data-view="spotify"><img src="${e(spotifyPlaylist.artwork)}" alt=""/><span>Echoes of the Unknown</span></button>${state.playlists.map(list=>`<button class="nav-item ${state.view==='playlist'&&state.viewId===list.id?'active':''}" data-action="open-playlist" data-id="${e(list.id)}">${icon('list',18)}<span>${e(list.name)}</span><small>${list.trackIds.length}</small></button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-status"><i></i><div><strong>Your music. Your space.</strong><small>Saved on this browser</small></div></div><button class="import-button" data-action="import">${icon('plus',17)} Import Music</button><button class="settings-link" data-action="settings">${icon('settings',16)} Settings & storage</button></div></aside>${state.sidebar?'<button class="sidebar-scrim" data-action="close-sidebar" aria-label="Close navigation"></button>':''}<div class="workspace"><header class="topbar"><div class="topbar-left">${button('sidebar','Open navigation','list','','mobile-menu')}${button('back','Go back','back')}${button('forward','Go forward','chevron')}<span class="topbar-divider"></span><span class="local-badge"><i></i> YOUR MUSIC, CONNECTED</span></div><div class="topbar-right"><span class="independent-label">Discover. Collect. Make it yours.</span>${button('theme','Toggle light or dark appearance',state.settings.theme==='dark'?'sun':'moon')}<button class="profile-button" data-action="settings">${icon('artist',15)}<span>My Library</span></button></div></header><main id="content" class="main-content" data-ready="${!state.loading}">${state.loading?'<div class="loading-screen">Opening your library…</div>':state.error?`<div class="empty-state">${icon('folder',40)}<h2>Let’s reconnect your library.</h2><p>${e(state.error)}</p><button class="primary" data-action="reload">Try again</button></div>`:renderContent()}</main><footer class="content-footer"><span>Music Lab · Independent reconstruction study</span><button data-action="about">About this project ${icon('info',12)}</button><span>Original demo recordings · import your own music</span></footer></div><section class="player ${active?'has-track':''}" aria-label="Music player"><div class="player-track"><button class="player-art" data-action="now-playing" aria-label="Open now playing"><img src="${cover(active)}" alt=""/></button><div class="player-track-copy"><strong id="now-title">${e(active?.title||'A little music goes a long way.')}</strong><button id="now-artist" data-action="current-artist">${e(active?.artist||'Choose something good. Press play.')}</button></div>${button('favorite-current','Favorite current track','heart','id="player-favorite" '+(!active?'disabled':''))}</div><div class="transport"><div class="transport-buttons">${button('shuffle','Toggle shuffle','shuffle','id="shuffle-button" aria-pressed="'+player.shuffle+'"')}${button('previous','Previous track','previous')}${button('toggle','Play','play','id="play-button"','play-button')}${button('next','Next track','next')}${button('repeat','Change repeat mode','repeat','id="repeat-button"')}</div><div class="seek-bar"><span id="elapsed">0:00</span><input id="seek" type="range" min="0" max="1000" step="1" value="0" aria-label="Playback position"/><span id="duration">${formatTime(active?.duration||0)}</span></div></div><div class="player-tools">${button('volume','Mute or restore volume','volume','id="volume-button"')}<input id="volume" aria-label="Volume" type="range" min="0" max="1" step=".01" value="${player.audio.volume}"/><span class="tool-divider"></span>${button('lyrics','Show lyrics','lyrics','aria-pressed="'+(state.panel==='lyrics')+'"')}${button('queue','Show playing next','list','aria-pressed="'+(state.panel==='queue')+'"')}${button('fullscreen','Open now playing','fullscreen')}</div></section>${state.panel?renderPanel():''}`;
  updatePlayer();
}
function sectionHead(title,action='',view='albums'){return `<div class="section-heading"><h2>${title}</h2>${action?`<button data-action="navigate" data-view="${view}">${action} ${icon('chevron',14)}</button>`:''}</div>`;}
function albumCards(items,classes='album-grid'){return `<div class="${classes}">${items.map(album=>`<article class="album-card"><div class="album-art"><button data-action="album" data-name="${e(album.name)}" data-artist="${e(album.artist)}" aria-label="Open album ${e(album.name)}"><img src="${album.cover}" alt="${e(album.name)} artwork" loading="lazy"/></button><button class="art-play" data-action="play-group" data-ids="${e(album.tracks.map(t=>t.id).join(','))}" aria-label="Play ${e(album.name)}">${icon('play',19)}</button></div><button class="album-name" data-action="album" data-name="${e(album.name)}" data-artist="${e(album.artist)}">${e(album.name)}</button><button class="album-artist" data-action="artist" data-name="${e(album.artist)}">${e(album.artist)}</button>${providerLink(album.tracks[0],true)}</article>`).join('')}</div>`;}
function miniTracks(tracks){return `<div class="mini-tracks">${tracks.map(track=>`<article class="mini-track" data-track="${e(track.id)}"><button class="mini-art" data-action="play" data-id="${e(track.id)}" aria-label="Play ${e(track.title)}"><img src="${cover(track)}" alt=""/><span>${icon('play',14)}</span></button><button class="mini-copy" data-action="play" data-id="${e(track.id)}"><strong>${e(track.title)}</strong><span>${e(track.artist)}</span></button>${providerLink(track,true)}${button('track-menu',`Options for ${track.title}`,'more',`data-id="${e(track.id)}"`)}</article>`).join('')}</div>`;}
function renderContent(){
  if(state.view==='new'||state.view==='home'){
    const allAlbums=albums().slice(0,8), topTracks=[...state.tracks].sort((a,b)=>Number(!!b.artwork)-Number(!!a.artwork)||b.addedAt-a.addedAt).slice(0,8), recent=[...state.tracks].filter(t=>t.lastPlayed).sort((a,b)=>b.lastPlayed-a.lastPlayed).slice(0,6);
    return `<div class="page-title"><div><h1>${state.view==='new'?'New':'Home'}</h1><p>A little discovery. A lot of you.</p></div><button class="discovery-search-button" data-action="discover" data-query="">${icon('search',17)} Find music</button></div>${renderHomeFeature(spotifyPlaylist,icon)}${state.view==='home'&&recent.length?sectionHead('Pick up where you left off')+miniTracks(recent):''}${sectionHead('Your library, on repeat','See All','songs')}${miniTracks(topTracks)}${sectionHead('Albums for the moment','Browse Albums','albums')}${albumCards(allAlbums,'album-shelf')}<section class="import-callout"><div class="import-callout-icon">${icon('headphones',32)}</div><div><h2>Your favorites belong here.</h2><p>Bring your MP3, M4A, FLAC or WAV files. Build playlists. Make it yours.</p><small>Files stay on this device. No upload required.</small></div><button class="primary" data-action="import">${icon('plus',16)} Import your music</button></section><div class="demo-note">Eight original instrumentals are included. Discover real songs with search, or import your own audio for full local playback.</div>`;

  }
  if(state.view==='spotify')return renderSpotify(spotifyPlaylist,state.playlists.some(list=>list.id===spotifySavedId),icon);
  if(state.view==='radio')return `<div class="page-title"><div><h1>Radio</h1><p>Find a frequency that feels like you.</p></div></div><div class="radio-feature"><span>YOUR PERSONAL STATION</span><h2>Let the music<br/>find its way.</h2><p>A shuffled mix from your library. No live broadcast.</p><button class="primary" data-action="station" data-genre="all">${icon('play',17)} Play My Station</button><div class="radio-orbits"></div></div>${sectionHead('Stations for your day')}<div class="station-grid">${[{name:'Late Night',genre:'Electronic',color:'casa',copy:'A little energy after dark.'},{name:'Quiet Hours',genre:'Ambient',color:'blue',copy:'Breathe in. Tune out.'},{name:'Deep Focus',genre:'Focus',color:'focus',copy:'Stay with the moment.'},{name:'Sunday Morning',genre:'Jazz',color:'sunday',copy:'Take your time.'}].map(station=>`<button class="station-card" data-action="station" data-genre="${station.genre}"><img src="/artwork/${station.color}.svg" alt=""/><div><span>${icon('radio',17)} LOCAL STATION</span><h3>${station.name}</h3><p>${station.copy}</p></div><span class="station-play">${icon('play',20)}</span></button>`).join('')}</div>`;
  if(state.view==='albums')return `<div class="page-title"><div><h1>Albums</h1><p>${albums().length} albums in your library</p></div><button class="secondary" data-action="import">${icon('plus',16)} Add Music</button></div>${albumCards(albums())}${!state.tracks.length?empty('No albums yet.','Import some music to start your collection.'):''}`;
  if(state.view==='artists'){const artists=[...new Set(state.tracks.map(t=>t.artist))].sort();return `<div class="page-title"><div><h1>Artists</h1><p>The people behind your soundtrack.</p></div></div><div class="artist-grid">${artists.map(name=>{const tracks=state.tracks.filter(t=>t.artist===name);return `<button class="artist-card" data-action="artist" data-name="${e(name)}"><img src="${cover(tracks[0])}" alt=""/><strong>${e(name)}</strong><small>${tracks.length} songs</small></button>`;}).join('')}</div>`;}
  if(state.view==='search')return `<div class="page-title"><div><h1>Search</h1><p>Your next favorite is out there.</p></div><span class="search-region">MOROCCO STORE</span></div><div class="search-tabs" role="group" aria-label="Search source"><button data-action="search-scope" data-scope="catalog" aria-pressed="${state.searchScope==='catalog'}">Discover music</button><button data-action="search-scope" data-scope="library" aria-pressed="${state.searchScope==='library'}">Your library</button></div><div class="big-search">${icon('search',23)}<input id="search-input" aria-label="${state.searchScope==='catalog'?'Search real music':'Search your library'}" placeholder="${state.searchScope==='catalog'?'Search any artist, song or album…':'Find a song in your library…'}" maxlength="200" value="${e(state.query)}" autocomplete="off"/>${button('clear-search','Clear search','close')}</div><div id="search-results" aria-live="polite">${renderSearchResults()}</div>`;

  const tracks=routeTracks();
  if(state.view==='album'||state.view==='artist'||state.view==='playlist'){
    const list=currentPlaylist(),name=state.view==='playlist'?(list?.name||'Playlist not found'):state.view==='album'?(albums().find(album=>album.id===state.viewId)?.name||'Album not found'):state.viewId;
    return `<section class="detail-header"><div class="detail-art ${state.view==='artist'?'round':''}"><img src="${safeArtwork(list?.artwork||tracks[0]?.artwork)}" alt="${e(name)}"/></div><div class="detail-copy"><span>${state.view.toUpperCase()}</span><h1>${e(name)}</h1><p>${state.view==='album'?e(tracks[0]?.artist||''):state.view==='artist'?'Artist in your library':list?.sourceUrl?'Saved from Spotify · first 100 public tracks':'Made by you. For every mood.'}</p><small>${tracks.length} songs · ${formatTime(tracks.reduce((sum,t)=>sum+t.duration,0))} total</small><div class="detail-actions"><button class="primary" data-action="play-visible" ${!tracks.some(isLocalAudio)?'disabled':''}>${icon('play',17)} Play</button><button class="secondary" data-action="shuffle-visible" ${!tracks.some(isLocalAudio)?'disabled':''}>${icon('shuffle',17)} Shuffle</button>${state.view==='playlist'&&list?button('playlist-menu','Playlist options','more',`data-id="${e(list.id)}"`):''}</div></div></section>${list?.sourceUrl?`<p class="playlist-coverage">100 of ${spotifyPlaylist.totalTrackCount.toLocaleString()} tracks were publicly available. <a href="${e(list.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open full playlist on Spotify ↗</a></p>`:''}${tracks.length?trackTable(tracks):empty('A good playlist starts with one song.','Use a song’s options menu to add it here.')}`;
  }
  const titles={songs:'Songs',favorites:'Favorite Songs',recent:'Recently Played'};
  return `<div class="page-title"><div><h1>${titles[state.view]||'Songs'}</h1><p>${tracks.length} songs · ${state.view==='favorites'?'All the ones you keep coming back to.':state.view==='recent'?'Your listening, lately.':'A soundtrack that’s entirely yours.'}</p></div><div class="page-actions"><button class="primary" data-action="play-visible" ${!tracks.some(isLocalAudio)?'disabled':''}>${icon('play',15)} Play</button><label class="sort-control">Sort by <select id="sort-select" aria-label="Sort songs"><option value="title" ${state.sort==='title'?'selected':''}>Title</option><option value="artist" ${state.sort==='artist'?'selected':''}>Artist</option><option value="added" ${state.sort==='added'?'selected':''}>Recently Added</option></select></label></div></div>${tracks.length?trackTable(tracks):empty(state.view==='favorites'?'Keep your favorites close.':'Your next favorite is waiting.',state.view==='favorites'?'Tap a song’s heart to save it here.':'Import music or play a song from New.')}`;
}
function empty(title,text){return `<div class="empty-state">${icon('music',43)}<h2>${title}</h2><p>${text}</p><button class="primary" data-action="import">Import Music</button></div>`;}
function renderSearchResults(){if(state.searchScope==='catalog')return renderCatalog({...catalog,query:state.query,savedIds:new Set(state.tracks.map(track=>track.id)),icon});const tracks=searchTracks(state.tracks,state.query);if(!state.query.trim())return `<div class="search-suggestions"><h2>Browse your moods</h2><div class="mood-grid">${['Focus','Electronic','Ambient','Pop','Jazz','Local music'].map((genre,index)=>`<button class="mood-card mood-${index%4}" data-action="genre" data-name="${e(genre)}"><strong>${e(genre)}</strong>${icon('chevron',16)}</button>`).join('')}</div>${state.settings.searchHistory?.length?`<h2>Recent searches</h2><div class="search-chips">${state.settings.searchHistory.map(query=>`<button data-action="search-term" data-name="${e(query)}">${icon('clock',13)}${e(query)}</button>`).join('')}</div>`:''}</div>`;return `<div class="search-count">${tracks.length} ${tracks.length===1?'result':'results'} in your library</div>${tracks.length?trackTable(tracks):empty('No matches just yet.','Try a different artist, title, album or genre.')}`;}
function trackTable(tracks){return `<div class="track-table" role="table" aria-label="Songs"><div class="table-header" role="row"><span>#</span><span>Title</span><span>Artist</span><span>Album</span><span>${icon('clock',14)}</span><span></span></div>${tracks.map((track,index)=>`<div class="track-row ${player.track?.id===track.id?'playing':''}" data-track="${e(track.id)}" data-occurrence="${index}" role="row"><button class="track-number" data-action="play" data-id="${e(track.id)}" aria-label="Play ${e(track.title)}"><span>${index+1}</span>${icon('play',13)}</button><div class="table-title"><button class="table-art" data-action="play" data-id="${e(track.id)}" aria-label="Play ${e(track.title)}"><img src="${cover(track)}" alt=""/></button><button data-action="play" data-id="${e(track.id)}"><strong>${e(track.title)}</strong><small>${e(track.source==='demo'?'Original demo':track.source==='catalog'?'Saved music link':track.artist)}</small></button>${providerLink(track,true)}</div><button class="table-artist" data-action="artist" data-name="${e(track.artist)}">${e(track.artist)}</button><button class="table-album" data-action="album" data-name="${e(track.album)}" data-artist="${e(track.artist)}">${e(track.album)}</button><span class="table-duration">${formatTime(track.duration)}</span><div class="table-options">${state.view==='playlist'?`<span class="playlist-reorder">${button('playlist-up','Move song up','up',`data-index="${index}" ${index===0?'disabled':''}`)}${button('playlist-down','Move song down','down',`data-index="${index}" ${index===tracks.length-1?'disabled':''}`)}</span>`:''}${button('favorite',track.favorite?`Unfavorite ${track.title}`:`Favorite ${track.title}`,'heart',`data-id="${e(track.id)}" aria-pressed="${!!track.favorite}"`,track.favorite?'icon-button favorite active':'icon-button favorite')}${button('track-menu',`Options for ${track.title}`,'more',`data-id="${e(track.id)}"`)}</div></div>`).join('')}</div>`;}
function renderPanel(){const track=player.track;return `<aside class="side-panel ${state.panel==='now'?'now-panel':''}" aria-label="${state.panel==='queue'?'Playing Next':state.panel==='lyrics'?'Lyrics':'Now Playing'}"><div class="panel-header"><h2>${state.panel==='queue'?'Playing Next':state.panel==='lyrics'?'Lyrics':'Now Playing'}</h2>${button('close-panel','Close panel','close')}</div>${state.panel==='queue'?`<div class="panel-subheading"><span>${player.queue.length} songs in queue</span><button data-action="clear-upcoming">Clear upcoming</button></div><div class="queue-list">${player.queue.length?player.queue.map((entry,index)=>{const t=findTrack(entry.trackId);return t?`<div class="queue-track ${index===player.index?'current':''}"><button class="queue-play" data-action="jump" data-index="${index}"><img src="${cover(t)}" alt=""/><span><strong>${e(t.title)}</strong><small>${e(t.artist)}</small></span></button><div class="queue-actions">${button('queue-up','Move up','up',`data-index="${index}" ${index===0?'disabled':''}`)}${button('queue-down','Move down','down',`data-index="${index}" ${index===player.queue.length-1?'disabled':''}`)}${button('queue-remove','Remove from queue','close',`data-index="${index}"`)}</div></div>`:'';}).join(''):'<p class="panel-empty">Start a song to build your queue.</p>'}</div>`:!track?'<div class="panel-empty">Choose a song to get started.</div>':state.panel==='now'?`<div class="now-content"><img class="now-large-art" src="${cover(track)}" alt="${e(track.album)}"/><h2>${e(track.title)}</h2><p>${e(track.artist)}</p><small>${e(track.album)}</small><div class="now-actions">${button('favorite-current','Favorite current track','heart')}${button('lyrics','Open lyrics','lyrics')}${button('queue','Open queue','list')}</div><div class="now-transport-tools">${button('shuffle','Toggle shuffle','shuffle',`aria-pressed="${player.shuffle}"`)}${button('repeat',`Repeat: ${player.repeat}`,'repeat')}${button('volume','Mute or restore volume',player.audio.volume?'volume':'mute')}<input id="now-volume" type="range" aria-label="Now playing volume" min="0" max="1" step=".01" value="${player.audio.volume}"/></div><p class="now-source">${track.source==='demo'?'Original Music Lab instrumental':'Playing from your local library'}</p></div>`:renderLyrics(track)}</aside>`;}
function renderLyrics(track){let parsed;try{parsed=parseLyrics(track.lyrics||'');}catch{return '<p class="panel-empty">These saved lyrics could not be read. Import a new lyrics file.</p>';}
  if(!track.lyrics)return `<div class="lyrics-empty">${icon('lyrics',42)}<h3>A little more meaning.</h3><p>${track.source==='demo'?'This demo is an instrumental.':'No lyrics have been added for this song.'}</p><p>Add a .lrc file for synchronized lyrics, or a .txt file to read along.</p><button class="primary" data-action="import-lyrics" data-id="${e(track.id)}">${icon('plus',15)} Add Lyrics</button></div>`;
  return `<div class="lyrics-heading"><strong>${e(track.title)}</strong><span>${e(track.artist)}</span><button data-action="import-lyrics" data-id="${e(track.id)}">Replace lyrics</button></div><div class="lyrics-lines ${parsed.timed?'timed':''}">${parsed.lines.map((line,index)=>parsed.timed?`<button data-action="lyric-seek" data-time="${line.time}" data-lyric-index="${index}">${e(line.text)||'♪'}</button>`:`<p>${e(line.text)||'&nbsp;'}</p>`).join('')}</div><p class="lyrics-source">Lyrics supplied by you · ${parsed.timed?'Click a line to seek':'Plain text'}</p>`;
}
function updatePlayer(){const track=player.track;const playing=player.isPlaying;const playButton=document.querySelector('#play-button');if(!playButton)return;playButton.innerHTML=icon(playing?'pause':'play',24);playButton.setAttribute('aria-label',playing?'Pause':'Play');playButton.title=player.loading?'Loading audio…':playing?'Pause':'Play';document.querySelector('#elapsed').textContent=formatTime(player.time);document.querySelector('#duration').textContent=formatTime(player.duration);const seek=document.querySelector('#seek');if(document.activeElement!==seek)seek.value=player.duration?String(player.time/player.duration*1000):'0';seek.style.setProperty('--range-fill',`${Number(seek.value)/10}%`);document.querySelector('#now-title').textContent=track?.title||'A little music goes a long way.';document.querySelector('#now-artist').textContent=track?.artist||'Choose something good. Press play.';document.querySelector('.player-art img').src=cover(track);document.querySelector('.player').classList.toggle('has-track',!!track);const favorite=document.querySelector('#player-favorite');favorite.disabled=!track;favorite.classList.toggle('active',!!track?.favorite);favorite.setAttribute('aria-pressed',String(!!track?.favorite));const shuffle=document.querySelector('#shuffle-button');shuffle.classList.toggle('active',player.shuffle);shuffle.setAttribute('aria-pressed',String(player.shuffle));const repeat=document.querySelector('#repeat-button');repeat.classList.toggle('active',player.repeat!=='off');repeat.setAttribute('aria-label',`Repeat: ${player.repeat}`);repeat.title=`Repeat: ${player.repeat}`;repeat.innerHTML=icon('repeat')+(player.repeat==='one'?'<b class="repeat-one">1</b>':'');document.querySelector('#volume-button').innerHTML=icon(player.audio.volume?'volume':'mute');const volume=document.querySelector('#volume');volume.value=player.audio.volume;volume.style.setProperty('--range-fill',`${player.audio.volume*100}%`);for(const row of document.querySelectorAll('[data-track]'))row.classList.toggle('playing',row.dataset.track===track?.id);if(state.panel==='lyrics'&&track?.lyrics){const parsed=parseLyrics(track.lyrics);const active=currentLyricIndex(parsed.lines,player.time);if(active!==renderedLyric){renderedLyric=active;for(const line of document.querySelectorAll('[data-lyric-index]'))line.classList.toggle('active',Number(line.dataset.lyricIndex)===active);const current=document.querySelector(`[data-lyric-index="${active}"]`);current?.scrollIntoView({block:'nearest',behavior:'smooth'});}}}
function showDialog(html){for(const audio of dialog.querySelectorAll('audio')){audio.pause();audio.removeAttribute('src');audio.load();}dialog.innerHTML=`${button('close-dialog','Close dialog','close','','dialog-close')}${html}`;dialog.showModal();dialog.querySelector('input,button:not(.dialog-close),a')?.focus();}
function trackMenu(track,occurrence){showDialog(`<div class="dialog-track"><img src="${cover(track)}" alt=""/><div><strong>${e(track.title)}</strong><span>${e(track.artist)}</span></div></div><div class="menu-actions"><button data-action="play" data-id="${e(track.id)}">${icon('play',17)} ${isLocalAudio(track)?'Play Now':'Open Preview & Provider'}</button>${isLocalAudio(track)?`<button data-action="play-next" data-id="${e(track.id)}">${icon('next',17)} Play Next</button><button data-action="play-last" data-id="${e(track.id)}">${icon('list',17)} Play Last</button>`:''}<button data-action="favorite" data-id="${e(track.id)}">${icon('heart',17)}${track.favorite?'Remove from Favorites':'Add to Favorites'}</button><button data-action="add-to-playlist" data-id="${e(track.id)}">${icon('plus',17)} Add to Playlist…</button><button data-action="edit-track" data-id="${e(track.id)}">${icon('edit',17)} Edit Song Info & Lyrics</button>${state.view==='playlist'?`<button data-action="remove-from-playlist" data-id="${e(track.id)}" data-index="${e(occurrence)}">${icon('list',17)} Remove from This Playlist</button>`:''}<button class="danger" data-action="remove-track" data-id="${e(track.id)}">${icon('delete',17)} Remove from Library</button></div>`);}
function settingsDialog(){showDialog(`<div class="dialog-eyebrow">YOUR MUSIC. YOUR SPACE.</div><h2>Settings & storage</h2><p>This library is saved in this browser on this device. Your imported audio is never uploaded. Clearing site data removes local imports and playlists.</p><div class="settings-stat"><strong>${state.tracks.filter(t=>t.source==='local').length}</strong><span>imported songs</span><strong>${state.playlists.length}</strong><span>playlists</span></div><label class="switch-label">Appearance<select id="theme-select"><option value="light" ${state.settings.theme!=='dark'?'selected':''}>Light</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Dark</option></select></label><button class="secondary full" data-action="persistent-storage">Keep library storage on this device</button><p class="small-copy">The browser decides whether persistent storage can be granted. Keep your original audio files as a backup.</p><hr/><h3>Apple Music connection</h3><p>Local playback is ready. Real music search and promotional previews are available in Discover music. Full Apple Music catalog and account features need a MusicKit developer token and Apple authorization, which you chose to configure later.</p><a class="inline-link" href="https://developer.apple.com/musickit/" target="_blank" rel="noopener noreferrer">MusicKit setup documentation ↗</a><hr/><h3>Keyboard shortcuts</h3><p>Space: play/pause · ← / →: seek 5 seconds · Ctrl/Cmd + K: search</p><button class="secondary full" data-action="restore-demos">Restore original demo collection</button>`);}
async function playTrack(id,ids,occurrence){
  const selected=findTrack(id);
  if(selected?.source==='catalog'){catalogPreview(selected);return;}
  const context=ids?.length?[...ids]:(['songs','favorites','recent','album','artist','playlist','search'].includes(state.view)?routeTracks().map(t=>t.id):state.tracks.map(t=>t.id));
  if(!context.includes(id))context.unshift(id);
  const index=Number.isInteger(occurrence)&&context[occurrence]===id?occurrence:context.indexOf(id);
  await player.setQueue(context,index,true);
}

function cancelCatalog(){clearTimeout(catalogTimer);catalogController?.abort();catalogController=null;++catalogGeneration;}
function refreshSearch(){const results=document.querySelector('#search-results');if(results)results.innerHTML=renderSearchResults();}
function scheduleCatalog(){
  cancelCatalog();
  const query=state.query.trim();
  if(state.searchScope!=='catalog'||state.view!=='search'||query.length<2){catalog={status:'idle',results:[],query,error:'',skipped:0};refreshSearch();return;}
  const generation=catalogGeneration;
  catalog={status:'loading',results:[],query,error:'',skipped:0};refreshSearch();
  catalogTimer=setTimeout(async()=>{
    const controller=new AbortController();catalogController=controller;
    const timeout=setTimeout(()=>controller.abort('timeout'),15000);
    try{catalogLastRequest=Date.now();const response=await searchCatalog(query,{signal:controller.signal});if(generation!==catalogGeneration)return;catalog={status:'done',query,results:response.tracks,skipped:response.skipped,error:''};}
    catch(error){if(generation!==catalogGeneration)return;catalog={status:'error',query,results:[],skipped:0,error:controller.signal.aborted?'The search timed out. Check your connection and try again.':error.message};}
    finally{clearTimeout(timeout);if(generation===catalogGeneration){catalogController=null;refreshSearch();}}
  },Math.max(650,3200-(Date.now()-catalogLastRequest)));
}
async function saveCatalogPlaylistTrack(track){if(findTrack(track.id))return;const saved=await addCatalogTrack(track);state.tracks.push(saved);}
function catalogPreview(track){
  player.audio.pause();
  const apple=track.provider==='itunes';
  showDialog(`<div class="preview-art"><img src="${cover(track)}" alt="${e(track.album||track.title)} artwork"/></div><div class="dialog-eyebrow">${apple?'ITUNES MUSIC DISCOVERY':'SAVED SPOTIFY SONG'}</div><h2>${e(track.title)}</h2><p class="preview-artist">${e(track.artist)}</p><p class="preview-album">${e(track.album)}${track.album?' · ':''}${formatTime(track.duration)} full track</p>${apple&&track.previewUrl?`<div class="preview-audio"><span>Song preview · provided courtesy of iTunes</span><audio controls preload="none" src="${e(track.previewUrl)}"></audio><p class="preview-feedback" role="status"></p></div>`:`<p>${apple?'No preview is available for this song.':'Listen to this song with Spotify, or search the Morocco catalog for available versions.'}</p>`}<div class="preview-actions">${providerLink(track)}${!findTrack(track.id)&&apple?`<button class="secondary" data-action="catalog-add" data-id="${e(track.id)}">${icon('plus',16)} Add to library</button>`:findTrack(track.id)?`<button class="secondary" data-action="add-to-playlist" data-id="${e(track.id)}">${icon('plus',16)} Add to playlist</button>`:''}</div>${!apple?`<button class="secondary full" data-action="discover" data-query="${e(track.title+' '+track.artist)}">${icon('search',16)} Search this song</button>`:''}<p class="small-copy">${apple?'This is a promotional preview. Open iTunes for the original track.':'Metadata and artwork provided by Spotify. Saving a link does not download audio.'}</p>`);
  const audio=dialog.querySelector('audio');
  audio?.addEventListener('error',()=>{const feedback=dialog.querySelector('.preview-feedback');if(feedback)feedback.textContent='This preview is unavailable. Open the original track using the provider link below.';});
}

async function changeTrack(id,patch){const updated=await updateTrack(id,patch);state.tracks=state.tracks.map(t=>t.id===id?updated:t);return updated;}
async function handleAction(action,target){const id=target.dataset.id,track=findTrack(id);switch(action){
 case 'discover':dialog.close();cancelCatalog();state.searchScope='catalog';state.query=target.dataset.query||'';catalog={status:'idle',results:[],query:state.query,error:'',skipped:0};navigate('search');scheduleCatalog();setTimeout(()=>document.querySelector('#search-input')?.focus(),0);break;
 case 'search-scope':cancelCatalog();state.searchScope=target.dataset.scope==='catalog'?'catalog':'library';render();if(state.searchScope==='catalog')scheduleCatalog();break;
 case 'retry-catalog':scheduleCatalog();break;
 case 'catalog-preview':{const item=catalog.results.find(item=>item.id===id)||track;if(item)catalogPreview(item);break;}
 case 'catalog-add':{if(catalogSavePending)break;const item=catalog.results.find(item=>item.id===id);if(item&&!findTrack(id)){catalogSavePending=true;try{await saveCatalogPlaylistTrack(item);notify('Added to your library. Use its options to add it to a playlist.');refreshSearch();if(dialog.open)catalogPreview(findTrack(id));}finally{catalogSavePending=false;}}break;}
 case 'save-spotify-playlist':{if(spotifySavePending)break;const existing=state.playlists.find(list=>list.id===spotifySavedId);if(existing){navigate('playlist',existing.id);break;}spotifySavePending=true;try{const tracks=spotifyLibraryTracks(spotifyPlaylist),list={id:spotifySavedId,name:spotifyPlaylist.title,trackIds:tracks.map(track=>track.id),createdAt:Date.now(),artwork:spotifyPlaylist.artwork,sourceUrl:spotifyPlaylist.requestedUrl,coverage:spotifyPlaylist.coverage};await saveCatalogPlaylist(tracks,list);const saved=await loadLibrary();state.tracks=saved.tracks;state.playlists=saved.playlists;navigate('playlist',list.id);notify('Saved 100 song links. Full playlist stays on Spotify.');}finally{spotifySavePending=false;}break;}

 case 'navigate':navigate(target.dataset.view);break;case 'album':{const matches=albums().filter(album=>album.name===target.dataset.name&&(!target.dataset.artist||album.artist===target.dataset.artist));if(matches.length===1)navigate('album',matches[0].id);else if(matches.length>1)showDialog(`<h2>Choose an album</h2><div class="menu-actions">${matches.map(album=>`<button data-action="album" data-name="${e(album.name)}" data-artist="${e(album.artist)}">${e(album.name)} ? ${e(album.artist)}</button>`).join('')}</div>`);break;}case 'artist':navigate('artist',target.dataset.name);break;case 'open-playlist':navigate('playlist',id);break;case 'back':history.back();break;case 'forward':history.forward();break;
 case 'sidebar':state.sidebar=!state.sidebar;render();break;case 'close-sidebar':state.sidebar=false;render();break;case 'reload':location.reload();break;case 'close-dialog':dialog.close();break;
 case 'import':if(!state.importing)document.querySelector('#audio-import').click();else notify('Your import is still in progress.');break;
 case 'play':dialog.close();await playTrack(id,undefined,Number(target.closest('[data-occurrence]')?.dataset.occurrence));break;case 'play-group':await playTrack(target.dataset.ids.split(',')[0],target.dataset.ids.split(',').filter(findTrack));break;
 case 'play-visible':{const ids=routeTracks().filter(isLocalAudio).map(t=>t.id);if(ids.length)await player.setQueue(ids,0,true);break;}case 'shuffle-visible':{const ids=shuffled(routeTracks().filter(isLocalAudio).map(t=>t.id));if(ids.length)await player.setQueue(ids,0,true);break;}
 case 'toggle':if(!player.track){if(state.tracks.some(isLocalAudio))await player.setQueue(state.tracks.filter(isLocalAudio).map(t=>t.id),0,true);else notify('Import a song to start listening.');}else await player.toggle();break;case 'next':await player.next();break;case 'previous':await player.previous();break;
 case 'shuffle':player.toggleShuffle();await persistSetting('shuffle',player.shuffle);break;case 'repeat':player.cycleRepeat();await persistSetting('repeat',player.repeat);break;case 'volume':player.mute();await persistSetting('volume',player.audio.volume);break;
 case 'favorite':if(track){await changeTrack(id,{favorite:!track.favorite});if(dialog.open)dialog.close();render();}break;
 case 'favorite-current':if(player.track){await changeTrack(player.track.id,{favorite:!player.track.favorite});render();}break;
 case 'current-artist':if(player.track)navigate('artist',player.track.artist);break;
 case 'now-playing':case 'fullscreen':state.panel=state.panel==='now'?null:'now';render();break;case 'queue':state.panel=state.panel==='queue'?null:'queue';render();break;case 'lyrics':state.panel=state.panel==='lyrics'?null:'lyrics';renderedLyric=-1;render();break;case 'close-panel':state.panel=null;render();break;
 case 'track-menu':if(track)trackMenu(track,target.closest('[data-occurrence]')?.dataset.occurrence);break;case 'play-next':case 'play-last':if(track&&!isLocalAudio(track)){notify('Open the saved music link to preview it or listen with its provider.');break;}if(track){player.enqueue(id,action==='play-next');dialog.close();notify(action==='play-next'?'Added to play next.':'Added to the end of your queue.');}break;
 case 'jump':await player.jump(Number(target.dataset.index));break;case 'queue-up':player.move(Number(target.dataset.index),Number(target.dataset.index)-1);break;case 'queue-down':player.move(Number(target.dataset.index),Number(target.dataset.index)+1);break;case 'queue-remove':player.remove(Number(target.dataset.index));break;case 'clear-upcoming':player.clearUpcoming();break;
 case 'genre':state.query=target.dataset.name;navigate('search');if(state.searchScope==='catalog')scheduleCatalog();break;case 'search-term':state.query=target.dataset.name;render();if(state.searchScope==='catalog')scheduleCatalog();break;case 'clear-search':cancelCatalog();state.query='';catalog={status:'idle',results:[],query:'',error:'',skipped:0};render();document.querySelector('#search-input')?.focus();break;
 case 'create-playlist':showDialog(`<div class="dialog-eyebrow">A SOUNDTRACK OF YOUR OWN</div><h2>New Playlist</h2><p>For late nights, long walks, or absolutely anything.</p><form data-form="playlist"><label>Name<input name="name" required maxlength="100" placeholder="Give it a name…" autocomplete="off"/></label><button class="primary full" type="submit">Create Playlist</button></form>`);break;
 case 'add-to-playlist':if(track)showDialog(`<h2>Add to Playlist</h2><p>${e(track.title)}</p><div class="menu-actions">${state.playlists.map(list=>`<button data-action="confirm-add-playlist" data-id="${e(id)}" data-playlist="${e(list.id)}">${icon('list',17)}${e(list.name)}</button>`).join('')}<button data-action="create-playlist">${icon('plus',17)}Create a playlist first</button></div>`);break;
 case 'confirm-add-playlist':{const list=state.playlists.find(p=>p.id===target.dataset.playlist);if(list&&track){const updated={...list,trackIds:[...list.trackIds,id]};await savePlaylist(updated);state.playlists=state.playlists.map(p=>p.id===list.id?updated:p);dialog.close();render();notify(`Added to ${list.name}.`);}break;}
 case 'playlist-menu':{const list=state.playlists.find(p=>p.id===id);if(list)showDialog(`<h2>${e(list.name)}</h2><form data-form="rename-playlist" data-id="${e(id)}"><label>Playlist name<input name="name" required maxlength="100" value="${e(list.name)}"/></label><button class="primary full">Save Name</button></form><button class="danger full" data-action="delete-playlist" data-id="${e(id)}">Delete Playlist</button>`);break;}
 case 'delete-playlist':if(window.confirm('Delete this playlist? Your songs will stay in the library.')){await removePlaylist(id);state.playlists=state.playlists.filter(p=>p.id!==id);dialog.close();navigate('songs');}break;
 case 'playlist-up':case 'playlist-down':{const list=currentPlaylist();if(list){const from=Number(target.dataset.index),to=from+(action==='playlist-up'?-1:1);const updated={...list,trackIds:moveItem(list.trackIds,from,to)};await savePlaylist(updated);state.playlists=state.playlists.map(p=>p.id===list.id?updated:p);render();}break;}
 case 'remove-from-playlist':{const list=currentPlaylist();if(list){const index=Number(target.dataset.index);if(!Number.isInteger(index)||list.trackIds[index]!==id)throw new Error('This playlist changed. Open the song options again.');const ids=[...list.trackIds];ids.splice(index,1);const updated={...list,trackIds:ids};await savePlaylist(updated);state.playlists=state.playlists.map(p=>p.id===list.id?updated:p);dialog.close();render();}break;}
 case 'edit-track':if(track)showDialog(`<h2>Song Info</h2><form data-form="track" data-id="${e(id)}">${['title','artist','album','genre'].map(field=>`<label>${field[0].toUpperCase()+field.slice(1)}<input name="${field}" value="${e(track[field])}" required maxlength="250"/></label>`).join('')}<label>Lyrics (.lrc timestamps or plain text)<textarea name="lyrics" rows="5" maxlength="100000">${e(track.lyrics)}</textarea></label><button class="primary full">Save Changes</button></form>`);break;
 case 'remove-track':if(track&&window.confirm(`Remove “${track.title}” from this library? Your original file will not be changed.`)){if(track.source==='demo'){await persistSetting('hiddenDemos',[...new Set([...(state.settings.hiddenDemos||[]),id])]);}await removeTrack(id);player.forget(id);state.tracks=state.tracks.filter(t=>t.id!==id);state.playlists=state.playlists.map(p=>({...p,trackIds:p.trackIds.filter(trackId=>trackId!==id)}));dialog.close();render();notify('Removed from your library.');}break;
 case 'import-lyrics':lyricsTargetId=id||player.track?.id;if(lyricsTargetId)document.querySelector('#lyrics-import').click();break;case 'lyric-seek':player.seek(Number(target.dataset.time));break;
 case 'theme':await persistSetting('theme',state.settings.theme==='dark'?'light':'dark');render();break;case 'settings':settingsDialog();break;
 case 'persistent-storage':{const granted=navigator.storage?.persist?await navigator.storage.persist():false;notify(granted?'Persistent library storage granted.':'The browser has not granted persistent storage. Keep your original files backed up.');break;}
 case 'restore-demos':await persistSetting('hiddenDemos',[]);for(const demo of demoTracks)if(!findTrack(demo.id)){await saveTrack(demo);state.tracks.push({...demo});}dialog.close();render();notify('Original demo collection restored.');break;
 case 'station':{let tracks=target.dataset.genre==='all'?state.tracks.filter(isLocalAudio):state.tracks.filter(isLocalAudio).filter(t=>t.genre.toLowerCase().includes(target.dataset.genre.toLowerCase()));if(!tracks.length){notify('Import songs in this genre to start this station.');break;}player.repeat='all';await player.setQueue(shuffled(tracks.map(t=>t.id)),0,true);notify('Your local station is playing.');break;}
 case 'about':showDialog(`<div class="dialog-eyebrow">A REVERSE-ENGINEERING STUDY</div><h2>Music, made personal.</h2><p>Music Lab is an independent local music player, informed by an inspection of Apple Music’s public web player and two captured JavaScript modules. It isn’t an Apple product.</p><p>Play your audio, make playlists, shape the queue, and add synchronized lyrics. Eight short original instrumentals are included to try the player immediately.</p><p>Your files, playlists, favorites and preferences live in this browser’s IndexedDB. They are not synced across devices. Keep your source files backed up.</p><p>Apple catalog streaming, personal Apple library access, Apple lyrics and recommendations are not connected. MusicKit setup can be added when you have the required developer token.</p><a class="inline-link" href="/investigation-report.html" target="_blank" rel="noopener">Read the investigation & feature coverage ↗</a>`);break;
 }}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;event.preventDefault();event.stopPropagation();void handleAction(target.dataset.action,target).catch(error=>notify(error.message||'That action could not be completed.'));});
document.addEventListener('input',event=>{if(event.target.id==='seek')player.seek(Number(event.target.value)/1000*player.duration);if(['volume','now-volume'].includes(event.target.id))player.setVolume(Number(event.target.value));if(event.target.id==='search-input'){state.query=event.target.value;refreshSearch();if(state.searchScope==='catalog')scheduleCatalog();}});
document.addEventListener('change',event=>{if(event.target.id==='sort-select'){state.sort=event.target.value;render();}if(['volume','now-volume'].includes(event.target.id))void persistSetting('volume',Number(event.target.value)).catch(error=>notify(error.message));if(event.target.id==='theme-select')void persistSetting('theme',event.target.value).then(render).catch(error=>notify(error.message));});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();void(async()=>{const data=new FormData(form);if(form.dataset.form==='playlist'){const name=String(data.get('name')).trim();if(!name)return;const list={id:crypto.randomUUID(),name,trackIds:[],createdAt:Date.now()};await savePlaylist(list);state.playlists.push(list);dialog.close();navigate('playlist',list.id);notify('Playlist created. Add songs from their options menu.');}if(form.dataset.form==='rename-playlist'){const list=state.playlists.find(p=>p.id===form.dataset.id);const updated={...list,name:String(data.get('name')).trim()};await savePlaylist(updated);state.playlists=state.playlists.map(p=>p.id===list.id?updated:p);dialog.close();render();}if(form.dataset.form==='track'){const patch=Object.fromEntries(data);for(const field of ['title','artist','album','genre'])patch[field]=String(patch[field]).trim();if(!patch.title)throw new Error('Give the song a title.');parseLyrics(patch.lyrics);await changeTrack(form.dataset.id,patch);dialog.close();renderedLyric=-1;render();}})().catch(error=>notify(error.message));});
dialog.addEventListener('close',()=>{for(const audio of dialog.querySelectorAll('audio')){audio.pause();audio.removeAttribute('src');audio.load();}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
document.querySelector('#audio-import').addEventListener('change',async event=>{const files=[...event.target.files];event.target.value='';if(!files.length||state.importing)return;state.importing=true;notify(`Importing ${files.length} ${files.length===1?'song':'songs'}…`);try{const result=await importAudioFiles(files,progress=>notify(`Importing music · ${progress.completed}/${progress.total}`));state.tracks.push(...result.tracks);render();if(result.errors.length)showDialog(`<h2>Import complete</h2><p>${result.tracks.length} songs imported. ${result.errors.length} files could not be imported.</p><div class="import-errors">${result.errors.map(error=>`<p><strong>${e(error.file)}</strong><br/>${e(error.message)}</p>`).join('')}</div><button class="primary full" data-action="close-dialog">Done</button>`);else notify(`${result.tracks.length} ${result.tracks.length===1?'song':'songs'} added to your library.`);}catch(error){notify(error.message);}finally{state.importing=false;}});
document.querySelector('#lyrics-import').addEventListener('change',async event=>{const file=event.target.files[0],id=lyricsTargetId;event.target.value='';if(!file||!id)return;try{if(file.size>400000)throw new Error('Choose a lyrics file smaller than 400 KB.');const lyrics=await file.text();parseLyrics(lyrics);await changeTrack(id,{lyrics});state.panel='lyrics';renderedLyric=-1;render();notify('Lyrics added.');}catch(error){notify(error.message);}});
document.addEventListener('keydown',event=>{if(event.target.id==='search-input'&&event.key==='Enter'&&state.query.trim()){void persistSetting('searchHistory',[state.query.trim(),...(state.settings.searchHistory||[]).filter(q=>q!==state.query.trim())].slice(0,8)).catch(error=>notify(error.message));}const tag=event.target.tagName;if(dialog.open||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(tag)||event.target.isContentEditable)return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();navigate('search');setTimeout(()=>document.querySelector('#search-input')?.focus(),0);}else if(event.code==='Space'){event.preventDefault();void handleAction('toggle',{dataset:{}}).catch(error=>notify(error.message));}else if(event.key==='ArrowRight'){event.preventDefault();player.seek(player.time+5);}else if(event.key==='ArrowLeft'){event.preventDefault();player.seek(player.time-5);}else if(event.key==='Escape'&&state.panel){state.panel=null;render();}});
player.addEventListener('update',event=>{
  updatePlayer();
  if(event.detail.type==='error'&&player.error)notify(player.error);
  if(['track','queue'].includes(event.detail.type)&&state.panel){renderedLyric=-1;render();}
  if(event.detail.type==='loaded'&&player.track){
    const track=player.track;
    void changeTrack(track.id,{lastPlayed:Date.now()}).catch(error=>notify(error.message));
    if('mediaSession'in navigator){
      try{navigator.mediaSession.metadata=new MediaMetadata({title:track.title,artist:track.artist,album:track.album,artwork:[{src:new URL(cover(track),location.href).href}]});}
      catch{/* Media Session may reject artwork formats without affecting audio. */}
    }
  }
  clearTimeout(saveQueueTimer);
  saveQueueTimer=setTimeout(()=>{void persistSetting('lastQueue',{ids:player.queue.map(entry=>entry.trackId),index:player.index}).catch(()=>{});},700);
});
if('mediaSession'in navigator){for(const [action,handler] of Object.entries({play:()=>player.isPlaying?undefined:player.toggle(),pause:()=>player.audio.pause(),previoustrack:()=>player.previous(),nexttrack:()=>player.next(),seekto:details=>player.seek(details.seekTime),seekbackward:details=>player.seek(player.time-(details.seekOffset||5)),seekforward:details=>player.seek(player.time+(details.seekOffset||5))})){try{navigator.mediaSession.setActionHandler(action,details=>Promise.resolve(handler(details)).catch(error=>notify(error.message)));}catch{/* Some browsers do not implement every media action. */}}}
window.addEventListener('hashchange',readRoute);window.addEventListener('beforeunload',()=>player.audio.pause());
render();
try{const saved=await loadLibrary();state={...state,...saved};for(const demo of demoTracks){if(!(state.settings.hiddenDemos||[]).includes(demo.id)&&!findTrack(demo.id)&&!saved.storedTrackIds.includes(demo.id)){await saveTrack(demo);state.tracks.push({...demo});}}player.setVolume(typeof state.settings.volume==='number'?state.settings.volume:.75);player.shuffle=state.settings.shuffle===true;player.repeat=['off','one','all'].includes(state.settings.repeat)?state.settings.repeat:'off';state.loading=false;readRoute();const last=state.settings.lastQueue;if(last&&Array.isArray(last.ids)&&Number.isInteger(last.index)&&last.ids.some(id=>isLocalAudio(findTrack(id)))){await player.setQueue(last.ids,last.index,false);}if(saved.warnings?.length)showDialog(`<h2>Some library records need attention</h2><p>Your valid music is still available. These records were left unchanged:</p><div class="import-errors">${saved.warnings.map(warning=>`<p>${e(warning)}</p>`).join('')}</div><button class="primary full" data-action="close-dialog">Continue</button>`);}catch(error){state.loading=false;state.error=error.message;render();}
